arguments.command:
mkdir -p /tmp/s; cat > /tmp/s/bb.py <<'EOF'
import sys,re
def bb(path):
    t=open(path,errors='ignore').read()
    pts=[]
    if path.endswith('.obj'):
        for l in t.splitlines():
            if l.startswith('v '):
                pts.append(list(map(float,l.split()[1:4])))
    else:
        for m in re.finditer(r'<float_array id="([^"]*)"[^>]*>([^<]*)<',t):
            if 'osition' not in m.group(1): continue
            v=list(map(float,m.group(2).split()))
            pts+= [v[i:i+3] for i in range(0,len(v)-2,3)]
        up=re.search(r'<up_axis>(\w+)<',t)
        if up and up.group(1)=='Z_UP':
            pts=[[p[0],p[2],-p[1]] for p in pts]
        # node matrices
        mats=re.findall(r'<matrix[^>]*>([^<]*)<',t)
        sc=re.findall(r'<scale[^>]*>([^<]*)<',t)
    if not pts: return None
    return [round(min(p[i] for p in pts),2) for i in range(3)],[round(max(p[i] for p in pts),2) for i in range(3)], len(pts)
for f in sys.argv[1:]:
    try: print(f, bb(f))
    except Exception as e: print(f,'ERR',e)
EOF
cd /app/data/models/ships; for d in */; do m=$(ls $d*.model|grep -v shield|head -1); c=$(grep -m1 '^collision' $m|awk '{print $2}'); l=$(grep -m1 '^lod' -A1 $m | grep -v lod | awk '{print $2}' | head -1); echo "== $d"; python3 -I /tmp/s/bb.py $d$c ; done

