cat > /tmp/s/bb2.py <<'EOF'
import sys
import xml.etree.ElementTree as ET
import numpy as np
NS='{http://www.collada.org/2005/11/COLLADASchema}'
def load(path):
    r=ET.parse(path).getroot()
    up=r.find(f'{NS}asset/{NS}up_axis')
    geoms={}
    for g in r.iter(f'{NS}geometry'):
        m=g.find(f'{NS}mesh')
        if m is None: continue
        vid=m.find(f'{NS}vertices/{NS}input[@semantic="POSITION"]').get('source')[1:]
        src=[s for s in m.findall(f'{NS}source') if s.get('id')==vid][0]
        a=np.array(src.find(f'{NS}float_array').text.split(),float).reshape(-1,3)
        geoms[g.get('id')]=a
    pts=[];tags={}
    def walk(n,M):
        mm=n.find(f'{NS}matrix')
        L=np.eye(4)
        if mm is not None: L=np.array(mm.text.split(),float).reshape(4,4)
        for t in n.findall(f'{NS}translate'):
            T=np.eye(4);T[:3,3]=list(map(float,t.text.split()));L=L@T
        M=M@L
        if (n.get('name') or '').startswith('tag_'): tags[n.get('name')]=M[:3,3].round(3)
        for ig in n.findall(f'{NS}instance_geometry'):
            a=geoms[ig.get('url')[1:]]
            h=np.c_[a,np.ones(len(a))]@M.T
            pts.append(h[:,:3])
        for c in n.findall(f'{NS}node'): walk(c,M)
    for vs in r.iter(f'{NS}visual_scene'):
        for n in vs.findall(f'{NS}node'): walk(n,np.eye(4))
    P=np.vstack(pts)
    return P.min(0).round(2),P.max(0).round(2),up.text if up is not None else None,tags.get('tag_landing')
for f in sys.argv[1:]:
    try: print(f,*load(f))
    except Exception as e: print(f,'ERR',e)
EOF
cd /app/data/models/ships; for d in */; do for m in $(ls $d*.model|grep -v shield); do c=$(grep -m1 '^collision' $m|awk '{print $2}'); h=$(grep '^mesh' $m | head -1 | awk '{print $2}'); echo "== $m"; [[ $c == *.dae ]] && python3 -I /tmp/s/bb2.py $d$c; python3 -I /tmp/s/bb2.py $d$h; done; done 2>&1

