def mm(A,B): return [[sum(A[i][k]*B[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
I=[[1 if i==j else 0 for j in range(4)] for i in range(4)]
for f in ['new_ground_hi.dae','new_ground_landing.dae','new_ground_coll.dae']:
    r=ET.parse(f).getroot()
    geoms={}
    for g in r.iter(f'{NS}geometry'):
        m=g.find(f'{NS}mesh')
        vid=m.find(f'{NS}vertices/{NS}input[@semantic="POSITION"]').get('source')[1:]
        src=[s for s in m.findall(f'{NS}source') if s.get('id')==vid][0]
        v=list(map(float,src.find(f'{NS}float_array').text.split()))
        geoms[g.get('id')]=[v[i:i+3] for i in range(0,len(v),3)]
    def walk(n,M):
        x=n.find(f'{NS}matrix'); L=I
        if x is not None:
            v=list(map(float,x.text.split()));L=[v[0:4],v[4:8],v[8:12],v[12:16]]
        M=mm(M,L)
        for ig in n.findall(f'{NS}instance_geometry'):
            P=[[sum(M[i][k]*p[k] for k in range(3))+M[i][3] for i in range(3)] for p in geoms[ig.get('url')[1:]]]
            # verts within pad areas
            for cx,cy in [(150,300),(-150,300),(150,0)]:
                zs=Counter(round(p[2],3) for p in P if abs(p[0]-cx)<50 and abs(p[1]-cy)<50)
                if zs: print(f,n.get('name'),(cx,cy),sorted(zs.items())[-6:])
        for c in n.findall(f'{NS}node'): walk(c,M)
    for vs in r.iter(f'{NS}visual_scene'):
        for n in vs.findall(f'{NS}node'): walk(n,I)
EOF

